import{_ as t,o as d,c as o,a3 as a}from"./chunks/framework.cNy3aYYk.js";const p=JSON.parse('{"title":"Leads created_by / updated_by (leads 1.6.0) — Production Readiness Audit","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Leads created_by / updated_by (leads 1.6.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/deployment/leads-created-by-updated-by-1-6-0-production-readiness"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Leads created_by / updated_by (leads 1.6.0) — Production Readiness Audit | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/deployment/leads-created-by-updated-by-1-6-0-production-readiness"}]]},"headers":[],"relativePath":"deployment/leads-created-by-updated-by-1-6-0-production-readiness.md","filePath":"deployment/leads-created-by-updated-by-1-6-0-production-readiness.md","lastUpdated":1790452722000}'),r={name:"deployment/leads-created-by-updated-by-1-6-0-production-readiness.md"};function s(n,e,i,l,c,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="leads-created-by-updated-by-leads-1-6-0-—-production-readiness-audit" tabindex="-1">Leads created_by / updated_by (leads 1.6.0) — Production Readiness Audit <a class="header-anchor" href="#leads-created-by-updated-by-leads-1-6-0-—-production-readiness-audit" aria-label="Permalink to &quot;Leads created_by / updated_by (leads 1.6.0) — Production Readiness Audit&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td><strong>Date</strong></td><td>2026-09-26</td></tr><tr><td><strong>Status</strong></td><td><strong>Go for production</strong> after migrate-first deploy + staging smoke</td></tr><tr><td><strong>Scope</strong></td><td>Tenant Leads module catalog <strong>1.5.0 → 1.6.0</strong> — denormalized <code>created_by</code> / <code>updated_by</code>, list/board/export filters, SPA columns + filters + overview</td></tr><tr><td><strong>Backend</strong></td><td>Columns + batched activity backfill; <code>LeadService</code> write + note/tag/follow-up touch paths; list/board filters (<code>system</code> = null); API <code>creator</code> / <code>updater</code>; catalog bump + CatalogSeeder; Pest <code>LeadCreatedByUpdatedByTest</code></td></tr><tr><td><strong>Frontend</strong></td><td>Table columns, Created by / Updated by filters (<code>ActorFilterSelect</code>), board badge, peek + record overview; Playwright <code>leads.created-by.spec.ts</code>; import e2e queue-worker hint</td></tr><tr><td><strong>Docs</strong></td><td>User / developer / API / database + changelog + hubs <strong>1.6.0</strong> + this audit</td></tr></tbody></table><p><strong>Companion docs:</strong> <a href="/deployment/leads">Leads deploy</a> · <a href="/deployment/upgrade">Upgrade</a> · <a href="/user-guide/leads">User guide</a> · <a href="/developer-guide/leads">Developer guide</a> · <a href="/api/tenant-v1-leads">API</a> · <a href="/changelog/">Changelog</a> · <a href="/developer-guide/playwright">Playwright</a></p><hr><h2 id="executive-summary" tabindex="-1">Executive summary <a class="header-anchor" href="#executive-summary" aria-label="Permalink to &quot;Executive summary&quot;">​</a></h2><p>Operators needed fast “who created / who last changed this lead?” filters without joining <code>lead_activities</code> on every list/board query. This ship <strong>denormalizes</strong> <code>leads.created_by</code> and <code>leads.updated_by</code> (nullable FKs → <code>users</code>, <code>nullOnDelete</code>), backfills from existing activity on migrate (batched), and keeps columns in sync on create/update/convert/restore/delete <strong>and</strong> notes / tag sync / follow-up mutations going forward.</p><p>SPA adds table columns, list filters (including <strong>System</strong> for null actors), board “By …” badge, and peek/record overview fields. No new permissions, no platform-shell changes (platform freeze).</p><p><strong>Go / No-Go:</strong> <strong>Go</strong> — all audit residuals remediated.</p><table tabindex="0"><thead><tr><th>Gate</th><th>Result</th></tr></thead><tbody><tr><td>Migrate-only catalog bump <code>leads</code> <strong>1.5.0 → 1.6.0</strong> + CatalogSeeder sync</td><td><strong>Pass</strong></td></tr><tr><td>Schema: nullable FKs + `(tenant_id, created_by</td><td>updated_by)` indexes</td></tr><tr><td>Batched backfill from <code>lead_activities</code> (created type → earliest actor → latest updater)</td><td><strong>Pass</strong></td></tr><tr><td><code>LeadService::create</code> sets both from authenticated actor; system/webhook leaves null</td><td><strong>Pass</strong></td></tr><tr><td>Notes / tags / follow-ups stamp <code>updated_by</code> when actor present</td><td><strong>Pass</strong> (I1 remediated)</td></tr><tr><td>Client cannot mass-assign <code>created_by</code> / <code>updated_by</code> (update <code>fill</code> allowlist)</td><td><strong>Pass</strong></td></tr><tr><td>List/board/stats share <code>created_by</code> / <code>updated_by</code> filters (<code>system</code> → <code>whereNull</code>)</td><td><strong>Pass</strong></td></tr><tr><td>Eager load <code>creator</code> / <code>updater</code>; API embeds + export columns</td><td><strong>Pass</strong></td></tr><tr><td>Import / Meta / custom webhook use <code>LeadService::create</code> (actor or null)</td><td><strong>Pass</strong></td></tr><tr><td>Duplicate-notification path prefers <code>created_by</code> over activity scan</td><td><strong>Pass</strong></td></tr><tr><td>Pest <code>LeadCreatedByUpdatedByTest</code> (4)</td><td><strong>Pass</strong> (35 assertions, local 2026-09-26)</td></tr><tr><td>Playwright <code>leads.created-by.spec.ts</code> one-session human flow</td><td><strong>Pass</strong></td></tr><tr><td>Import e2e documents / fails clearly without <code>imports</code> worker</td><td><strong>Pass</strong> (I2 remediated)</td></tr><tr><td>User / developer / API / database / changelog / roadmap hubs</td><td><strong>Pass</strong></td></tr><tr><td>New permission / env / queue / seeder required for cutover</td><td><strong>N/A</strong></td></tr></tbody></table><hr><h2 id="security-summary" tabindex="-1">Security summary <a class="header-anchor" href="#security-summary" aria-label="Permalink to &quot;Security summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Control</th><th>Status</th></tr></thead><tbody><tr><td>No new endpoints or Spatie permissions</td><td>Pass</td></tr><tr><td>Module gate <code>module:leads</code> + existing <code>leads.*</code> unchanged</td><td>Pass</td></tr><tr><td>Tenant isolation unchanged (columns on tenant <code>leads</code>)</td><td>Pass</td></tr><tr><td>Request payloads cannot set actor columns</td><td>Pass</td></tr><tr><td>Filter values are user id or <code>system</code> — no extra PII beyond existing list embeds</td><td>Pass</td></tr><tr><td>Soft-delete / restore still permission-gated; restore stamps <code>updated_by</code></td><td>Pass</td></tr></tbody></table><h3 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h3><table tabindex="0"><thead><tr><th>ID</th><th>Severity</th><th>Item</th><th>Disposition</th></tr></thead><tbody><tr><td><strong>I1</strong></td><td>Info</td><td>Notes, tags, follow-ups alone did not bump <code>updated_by</code></td><td><strong>Remediated</strong> — <code>LeadService</code> stamps <code>updated_by</code> on note add, tag sync (when tags/follow-up change), follow-up create/update/complete</td></tr><tr><td><strong>L1</strong></td><td>Low</td><td>Migrate backfill was O(leads × 2) per-row activity lookups</td><td><strong>Remediated</strong> — chunk 500 with aggregate MIN/MAX activity id queries per chunk</td></tr><tr><td><strong>L2</strong></td><td>Low</td><td>Pre-<code>created</code> activity leads stayed null</td><td><strong>Remediated</strong> — fall back to earliest activity with <code>user_id</code> for <code>created_by</code>; latest actor (else created_by) for <code>updated_by</code>. True orphans remain <strong>System</strong></td></tr><tr><td><strong>I2</strong></td><td>Info</td><td>Playwright import specs timed out without queue worker</td><td><strong>Remediated</strong> — <code>npm run test:e2e:leads</code> prints worker hint; import helper throws actionable Status:completed timeout; import spec documents worker command</td></tr></tbody></table><p>No open residuals.</p><hr><h2 id="change-inventory" tabindex="-1">Change inventory <a class="header-anchor" href="#change-inventory" aria-label="Permalink to &quot;Change inventory&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ul><li>Migration <code>2026_09_26_112037_add_created_by_and_updated_by_to_leads_table</code> — columns, FKs, indexes, <strong>batched</strong> activity backfill with created-type + earliest-actor fallbacks.</li><li>Migration <code>2026_09_26_112040_bump_leads_module_to_1_6_0</code> — <code>DefaultModuleRegistrar::bumpVersion(&#39;leads&#39;, &#39;1.6.0&#39;)</code>.</li><li>Migration <code>2026_09_26_133208_remediates_leads_created_by_updated_by_backfill</code> — idempotent re-fill for rows still null (L1/L2 remediations on already-migrated DBs).</li><li><code>CatalogSeeder</code> leads version <strong>1.6.0</strong>.</li><li><code>Lead</code> model: fillable + <code>creator</code> / <code>updater</code> relations.</li><li><code>LeadService</code>: create stamps; update/assign/stage/convert/restore/delete; <strong>notes/tags/follow-ups</strong> via <code>touchUpdatedBy</code>; list/board filters; eager loads.</li><li><code>ListLeadResource</code> (+ show resources): <code>created_by</code> / <code>updated_by</code> + embedded users.</li><li><code>LeadsExport</code>: Created by / Updated by name columns.</li><li><code>LeadEventSubscriber</code>: duplicate notify prefers <code>created_by</code>.</li><li>Factory / Pest: <code>LeadCreatedByUpdatedByTest</code> (create/update, filters, system, <strong>touch paths</strong>).</li></ul><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ul><li><code>ActorFilterSelect</code> + leads list filters / URL params.</li><li>Table columns, board badge, peek + record overview.</li><li>Types: lead <code>creator</code> / <code>updater</code>.</li><li>Playwright: <code>e2e/tests/leads/leads.created-by.spec.ts</code>; import queue-worker hint + clear timeout error.</li></ul><h3 id="docs" tabindex="-1">Docs <a class="header-anchor" href="#docs" aria-label="Permalink to &quot;Docs&quot;">​</a></h3><ul><li>Changelog delivery note; user guide + overview; developer guide; API query params; database schema; product roadmap hubs <strong>1.6.0</strong>.</li><li>This production readiness audit (residuals closed); Upgrade + Leads deploy + Playwright cross-links.</li></ul><hr><h2 id="test-evidence" tabindex="-1">Test evidence <a class="header-anchor" href="#test-evidence" aria-label="Permalink to &quot;Test evidence&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Result</th><th>Notes</th></tr></thead><tbody><tr><td><code>herd php artisan test --compact tests/Feature/Tenant/Lead/LeadCreatedByUpdatedByTest.php</code></td><td><strong>4 passed</strong>, 35 assertions</td><td>Create/update; list/board filters; system; note/tag <code>updated_by</code></td></tr><tr><td>Playwright <code>e2e/tests/leads/leads.created-by.spec.ts</code></td><td><strong>Pass</strong></td><td>Single demo login session</td></tr><tr><td>Companion Leads import e2e</td><td><strong>Pass with worker</strong></td><td>Requires <code>queue:work --queue=imports,default</code>; timeout message documents the requirement</td></tr></tbody></table><hr><h2 id="staging-smoke" tabindex="-1">Staging smoke <a class="header-anchor" href="#staging-smoke" aria-label="Permalink to &quot;Staging smoke&quot;">​</a></h2><ol><li>Confirm catalog <code>leads.version</code> = <strong>1.6.0</strong> after migrate (do <strong>not</strong> <code>db:seed</code>).</li><li>Open Leads <strong>Table</strong> → columns <strong>Created by</strong> / <strong>Updated by</strong> visible.</li><li>Create a lead as a known user → row shows that name; filter <strong>Created by</strong> = that user keeps the row; <strong>System</strong> hides it.</li><li>Edit the lead as a second user → <strong>Updated by</strong> updates; <strong>Created by</strong> unchanged.</li><li>Add a note (or change tags) as a third user → <strong>Updated by</strong> becomes that user.</li><li>Board: search the lead → “By …” badge matches creator.</li><li>Peek + full record Overview show Created by / Updated by.</li><li>Spot-check one webhook/import lead → <strong>System</strong> (or importer when import ran as a user).</li><li>Export CSV → Created by / Updated by columns populated.</li></ol><hr><h2 id="deploy" tabindex="-1">Deploy <a class="header-anchor" href="#deploy" aria-label="Permalink to &quot;Deploy&quot;">​</a></h2><ol><li>Deploy <strong>Backend</strong> with both migrations.</li><li><code>php artisan migrate --force</code> (central catalog bump + each tenant DB columns/backfill).</li><li><code>php artisan queue:restart</code> (no new queues; restart picks up code).</li><li>Deploy <strong>Frontend</strong> (filters/columns).</li><li>Deploy <strong>Docs</strong>.</li><li>Staging smoke above.</li></ol><p>No new env keys. No RBAC migration. No <code>db:seed</code>.</p><h3 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h3><ul><li>Redeploy previous Backend + run migration <code>down</code> only if columns must be dropped (data loss of denormalized stamps; activity history remains).</li><li>Prefer leave columns in place and roll back SPA only if UI must revert — old API ignores unused embeds safely; new filters ignore unknown query params on old Backend until upgraded.</li></ul><hr><h2 id="sign-off" tabindex="-1">Sign-off <a class="header-anchor" href="#sign-off" aria-label="Permalink to &quot;Sign-off&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Role</th><th>Decision</th><th>Date</th></tr></thead><tbody><tr><td>Engineering</td><td><strong>Go</strong> — I1/L1/L2/I2 remediated</td><td>2026-09-26</td></tr><tr><td>Ops</td><td>☐ Staging smoke</td><td></td></tr><tr><td>Product</td><td><strong>Go</strong> — Updated by includes notes/tags/follow-ups</td><td>2026-09-26</td></tr></tbody></table><p><strong>Current decision (2026-09-26):</strong> <strong>Go</strong> — residuals closed; merge after CI green; migrate-first; complete staging smoke before production traffic.</p>',39)])])}const h=t(r,[["render",s]]);export{p as __pageData,h as default};
